import{_ as l,l as i,o as e,c as o,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"持久性等级","description":"","frontmatter":{"title":"持久性等级","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/durability-levels.md","filePath":"cs/durability-levels.md","lastUpdated":1789023840000}'),h={name:"cs/durability-levels.md"};function _(A,a,u,m,f,E){const s=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="持久性等级" tabindex="-1">持久性等级 <a class="header-anchor" href="#持久性等级" aria-label="Permalink to &quot;持久性等级&quot;">​</a></h1><div class="epigraph"><p>D 不是布尔：同步刷本地日志、异步返回、等备库落盘，对应不同的丢失窗口。合同要写 RPO，不能只写 ACID 的 D。</p><footer>—— 据 Gray and Reuter；HA 与复制实践；主干 ACID 的 D 分级</footer></div><p><a href="/cs/group-commit">上一课</a>摊了 fsync。本课把「刷到什么程度算提交成功」分级。主干 ACID 把 D 当日志持久。工程上异步提交、内存队列、只等备库中的一条，都在卖延迟。缺口是<strong>显式 RPO</strong>（恢复点目标），RTO 下一课谈时间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>等级例子：① 本地 WAL sync（默认 D）；② 本地 WAL 异步（崩溃丢一组）；③ 同步复制到备库内存；④ 备库也 fsync。每一档延迟与丢失窗口不同。缺口不是道德指责「假持久」，而是应用与库的合同必须一致：支付系统与点赞计数不是同一档。</p><p>组提交在每一档内部仍可做。半同步后课是③/④ 的一种产品形态。</p><p><span class="marginnote">RPO=0 意味同步持久到约定故障域。电池后备的磁盘缓存使 fsync 语义变糊，合同要包含控制器。本课不测硬件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>会话或事务设耐久级别。返回成功则按该级保证。降级：备库断开时从④退到①并告警，还是拒绝写入——策略。只读不涉及 D。</p><p>与 TDE：未刷的明文缓冲被偷是另一威胁模型，不单是崩溃。</p>',10)),(e(),n(p,null,{default:r(()=>[c(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E6%8F%90%E4%BA%A4%E8%BF%94%E5%9B%9E%22%5D%20--%3E%20L1%5B%22%E6%9C%AC%E5%9C%B0%20sync%20WAL%22%5D%0A%20%20C%20--%3E%20L2%5B%22%E6%9C%AC%E5%9C%B0%20async%22%5D%0A%20%20C%20--%3E%20L3%5B%22%E5%A4%87%E5%BA%93%E6%94%B6%E5%88%B0%22%5D%0A%20%20C%20--%3E%20L4%5B%22%E5%A4%87%E5%BA%93%20sync%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>崩溃恢复：① 丢未刷；② 丢更多；③ 主挂备升可能丢或用共识避免双主。双主脑裂是复制课。基准：TPC-C 规定耐久，关 fsync 的数字不能比。</p><p>应用重试：异步提交下「成功返回」仍可能丢失，幂等要按更弱合同设计——与网络课幂等衔接，这里点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不计算 RTO 分钟数。也不把云多 AZ 的每一家 SLA 抄进来。备份 PITR 是另一时间轴。</p><p>后课默认：D 有等级；默认教学仍是本地 sync WAL。RTO 与恢复：从崩溃到可服务的时间，检查点与 redo 速度决定。</p><p>没有写明的 D，基准与事故复盘都无法谈丢失窗口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>持久性从本地 sync 到跨机 sync 分档，对应 RPO。</li><li>降级策略要显式；基准必须声明档位。</li><li>RTO 与恢复下一课。</li><li>出处：Gray and Reuter；复制 HA 实践。</li></ul>',9))])}const D=l(h,[["render",_]]);export{C as __pageData,D as default};
